student_id = #{studentId}, subject = #{subject}, total_hours = #{totalHours}, used_hours = #{usedHours}, total_amount = #{totalAmount}, teacher_user_id = #{teacherUserId}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime},
